CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TYPE "Phase" AS ENUM ('PRE','POST'); CREATE TYPE "ItemResult" AS ENUM ('PENDING','PASS','NA','ISSUE'); CREATE TYPE "ReleaseStatus" AS ENUM ('PLANNED','IN_PROGRESS','BLOCKED','COMPLETED'); CREATE TYPE "EventType" AS ENUM ('CREATED','ITEM_UPDATED','COMPLETED');
CREATE TABLE "Site" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"name" varchar(50) NOT NULL,"description" varchar(200),"archivedAt" timestamptz,"revision" integer NOT NULL DEFAULT 1,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX "Site_name_lower_key" ON "Site" (lower("name"));
CREATE TABLE "TemplateItem" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"siteId" uuid REFERENCES "Site"("id") ON DELETE RESTRICT,"phase" "Phase" NOT NULL,"label" varchar(150) NOT NULL,"sortOrder" integer NOT NULL DEFAULT 0,"active" boolean NOT NULL DEFAULT true,"revision" integer NOT NULL DEFAULT 1,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now()); CREATE INDEX "TemplateItem_site_active_phase_order_idx" ON "TemplateItem"("siteId","active","phase","sortOrder");
CREATE TABLE "Release" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"createKey" uuid NOT NULL UNIQUE,"createPayloadHash" varchar(64) NOT NULL,"siteId" uuid NOT NULL REFERENCES "Site"("id") ON DELETE RESTRICT,"siteNameSnapshot" varchar(50) NOT NULL,"title" varchar(80) NOT NULL,"versionLabel" varchar(30) NOT NULL,"ownerName" varchar(30) NOT NULL,"description" text,"scheduledDate" date NOT NULL,"status" "ReleaseStatus" NOT NULL DEFAULT 'PLANNED',"revision" integer NOT NULL DEFAULT 1,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"completedAt" timestamptz); CREATE INDEX "Release_status_created_idx" ON "Release"("status","createdAt"); CREATE INDEX "Release_site_created_idx" ON "Release"("siteId","createdAt");
CREATE TABLE "ReleaseItem" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"releaseId" uuid NOT NULL REFERENCES "Release"("id") ON DELETE RESTRICT,"templateItemId" uuid REFERENCES "TemplateItem"("id") ON DELETE RESTRICT,"phase" "Phase" NOT NULL,"label" varchar(150) NOT NULL,"sortOrder" integer NOT NULL,"result" "ItemResult" NOT NULL DEFAULT 'PENDING',"note" text NOT NULL DEFAULT '',"checkedAt" timestamptz,"checkedBy" varchar(50)); CREATE INDEX "ReleaseItem_release_phase_order_idx" ON "ReleaseItem"("releaseId","phase","sortOrder");
CREATE TABLE "ReleaseEvent" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"releaseId" uuid NOT NULL REFERENCES "Release"("id") ON DELETE RESTRICT,"itemId" uuid REFERENCES "ReleaseItem"("id") ON DELETE RESTRICT,"type" "EventType" NOT NULL,"actorId" varchar(50) NOT NULL,"before" jsonb,"after" jsonb,"createdAt" timestamptz NOT NULL DEFAULT now()); CREATE INDEX "ReleaseEvent_release_created_id_idx" ON "ReleaseEvent"("releaseId","createdAt","id");
